 void metrics(){android.util.DisplayMetrics m=new android.util.DisplayMetrics();wm.getDefaultDisplay().getRealMetrics(m);width=m.widthPixels;height=m.heightPixels;rotation=wm.getDefaultDisplay().getRotation();}
 void makeRunner(){runner=new AutoTapRunner(plan,new AutoTapRunner.Scheduler(){public long now(){return SystemClock.uptimeMillis();}public void post(Runnable r,long ms){handler.postDelayed(r,ms);}public void cancel(Runnable r){handler.removeCallbacks(r);}},this::dispatch,this::blocked,this::changed);}
 String blocked(){if(service.editorOpen)return "App editor open · paused";if(!service.getSharedPreferences("config",0).getBoolean("tap",false))return "Enable Allow actions in Auto Tap";if(!((PowerManager)service.getSystemService(Context.POWER_SERVICE)).isInteractive()||((KeyguardManager)service.getSystemService(Context.KEYGUARD_SERVICE)).isKeyguardLocked())return "Screen off or locked · paused";if(wm.getDefaultDisplay().getRotation()!=rotation)return "Display changed · check positions before Play";if(SystemClock.uptimeMillis()<service.autoTapBusyUntil)return "Previous gesture is finishing · try Play again";for(AutoTapPlan.Point p:plan.points)if(controls.contains(x(p),y(p)))return "A target is under the controls · move the menu";return null;}
