 boolean dispatch(int i,int hold,AutoTapRunner.Result result){AutoTapPlan.Point p=plan.points.get(i);Path path=new Path();path.moveTo(x(p),y(p));GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(path,0,hold)).build();long lease=service.beginAutoTapStroke(hold);try{boolean accepted=service.sendTapGesture(g,new AccessibilityService.GestureResultCallback(){public void onCompleted(GestureDescription ignored){service.endAutoTapStroke(lease);result.finish(true);}public void onCancelled(GestureDescription ignored){service.endAutoTapStroke(lease);result.finish(false);}});if(!accepted)service.endAutoTapStroke(lease);return accepted;}catch(RuntimeException e){service.endAutoTapStroke(lease);throw e;}}
 void changed(){if(closed)return;if(reloadRequested&&!runner.pending){reloadRequested=false;replace(AutoTapStore.load(service));return;}long now=SystemClock.uptimeMillis();if(!runner.playing){AutoTapStore.progress(service,runner,true);lastPersist=now;update();}else if(now-lastUi>=250)update();}
 void toggle(){if(runner.playing){runner.pause("Paused · drag targets to adjust");return;}if(runner.pending)return;metrics();cacheControls();removeMarkers();rateStart=SystemClock.uptimeMillis();rateCount=runner.taps;rate=0;runner.remaining=Math.max(80,runner.remaining);runner.play();update();}
 void update(){if(closed||panel==null)return;long now=SystemClock.uptimeMillis();lastUi=now;if(runner.playing&&now-rateStart>=1000){rate=1000.0*(runner.taps-rateCount)/(now-rateStart);rateStart=now;rateCount=runner.taps;}status.setText(runner.pending&&!runner.playing?"Finishing the current tap…":runner.playing?"Running · target "+(runner.index+1)+" / "+plan.points.size():runner.message);stats.setText(String.format(Locale.US,"%d taps · %d cycles\n%.1f completed/s",runner.taps,runner.cycles,runner.playing?rate:0));play.setText(runner.playing?"Pause":runner.done?"Replay":"Play");play.setEnabled(!runner.pending||runner.playing);for(Button b:new Button[]{targets,numbers,speed,layouts})b.setEnabled(!runner.pending);if(runner.playing||runner.pending)removeMarkers();else if(markerVisible&&markers.isEmpty())showMarkers();targets.setText(markerVisible?"Hide points":"Show points");numbers.setText("Tap points · "+plan.points.size());}
 Button control(LinearLayout row,String text,Runnable action){Button b=Ui.button(service,text,false);b.setTextSize(15);b.setPadding(Ui.dp(service,4),0,Ui.dp(service,4),0);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,Ui.dp(service,Math.max(52,36*service.getResources().getConfiguration().fontScale)),1);lp.setMargins(Ui.dp(service,4),Ui.dp(service,4),Ui.dp(service,4),Ui.dp(service,4));row.addView(b,lp);b.setOnClickListener(v->action.run());return b;}
 LinearLayout row(){LinearLayout r=new LinearLayout(service);panel.addView(r);return r;}
 void buildPanel(){panel=Ui.column(service);panel.setPadding(Ui.dp(service,10),Ui.dp(service,10),Ui.dp(service,10),Ui.dp(service,10));panel.setBackground(Ui.shape(service,Ui.SURFACE,Ui.GREEN,22));LinearLayout title=row();title.setGravity(Gravity.CENTER_VERTICAL);BrainView brain=new BrainView(service,false);title.addView(brain,new LinearLayout.LayoutParams(Ui.dp(service,28),Ui.dp(service,28)));TextView heading=Ui.label(service,"Auto Tap · drag here",16,Ui.CREAM);heading.setPadding(Ui.dp(service,8),0,0,0);heading.setContentDescription("Auto Tap controls. Drag to move.");title.addView(heading,new LinearLayout.LayoutParams(0,Ui.dp(service,42),1));status=Ui.label(service,"Ready",15,Ui.CREAM);status.setMaxLines(2);status.setEllipsize(android.text.TextUtils.TruncateAt.END);panel.addView(status,new LinearLayout.LayoutParams(-1,Ui.dp(service,44*service.getResources().getConfiguration().fontScale)));stats=Ui.label(service,"",14,Ui.MUTED);stats.setMaxLines(2);panel.addView(stats,new LinearLayout.LayoutParams(-1,Ui.dp(service,48*service.getResources().getConfiguration().fontScale)));
  LinearLayout first=row();targets=control(first,"Targets",()->{runner.pause("Paused · target editing");markerVisible=!markerVisible;removeMarkers();update();});numbers=control(first,"Number",()->edit(()->AutoTapUi.count(service,plan,this::replace)));
  LinearLayout second=row();speed=control(second,"Speed",()->edit(()->AutoTapUi.settings(service,plan,this::replace)));layouts=control(second,"Layouts",()->edit(()->AutoTapUi.profiles(service,plan,this::replace)));
  LinearLayout third=row();play=control(third,"Play",this::toggle);Ui.styleButton(play,true);Button stop=control(third,"Stop",()->service.closeAutoTap(false));stop.setTextColor(Ui.RED);
  final boolean[] handled={false};play.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN&&runner.playing){handled[0]=true;runner.pause("Paused · drag targets to adjust");return true;}if(handled[0]){if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)handled[0]=false;return true;}return false;});stop.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN){service.closeAutoTap(false);return true;}return false;});
  LinearLayout details=Ui.column(service);for(View child:new View[]{stats,first,second}){panel.removeView(child);details.addView(child);}ScrollView scroll=new ScrollView(service);scroll.setFillViewport(false);scroll.addView(details);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  popupScale=PopupSize.scale(service,"advancedPopupSize",300,370);PopupSize.tree(panel,popupScale);panelParams=params(Ui.dp(service,300*popupScale),Ui.dp(service,370*popupScale));panelParams.x=Math.round(AutoTapStore.prefs(service).getFloat("panelX",12)*service.getResources().getDisplayMetrics().density);panelParams.y=Math.round(AutoTapStore.prefs(service).getFloat("panelY",80)*service.getResources().getDisplayMetrics().density);clampPanel();wm.addView(panel,panelParams);heading.setOnTouchListener(dragPanel());brain.setOnTouchListener(dragPanel());panel.post(this::cacheControls);
 }
 WindowManager.LayoutParams params(int w,int h){WindowManager.LayoutParams p=new WindowManager.LayoutParams(w,h,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.layoutInDisplayCutoutMode=WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_ALWAYS;return p;}
 void clampPanel(){if(panel==null||panelParams==null)return;panelParams.width=Math.min(Ui.dp(service,300*popupScale),width);panelParams.height=Math.min(Ui.dp(service,370*popupScale*service.getResources().getConfiguration().fontScale),height-Ui.dp(service,16));panel.measure(View.MeasureSpec.makeMeasureSpec(panelParams.width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(panelParams.height,View.MeasureSpec.EXACTLY));panelParams.x=Math.max(0,Math.min(panelParams.x,width-panelParams.width));panelParams.y=Math.max(0,Math.min(panelParams.y,height-panel.getMeasuredHeight()));if(panel.isAttachedToWindow())wm.updateViewLayout(panel,panelParams);cacheControls();}
