 View.OnTouchListener dragPanel(){return new View.OnTouchListener(){float x,y;int ox,oy;public boolean onTouch(View v,MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){runner.pause("Paused · moving controls");x=e.getRawX();y=e.getRawY();ox=panelParams.x;oy=panelParams.y;return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){panelParams.x=ox+Math.round(e.getRawX()-x);panelParams.y=oy+Math.round(e.getRawY()-y);clampPanel();return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){savePosition();return true;}return true;}};}
 void edit(Runnable open){runner.pause("Paused · editing layout");if(!runner.pending)open.run();}
 void replace(AutoTapPlan p){p.validate();AutoTapStore.save(service,p);runner.stop();plan=p;removeMarkers();makeRunner();markerVisible=true;AutoTapStore.progress(service,runner,true);showMarkers();update();}
 void resize(){float next=PopupSize.scale(service,"advancedPopupSize",300,370);PopupSize.tree(panel,next/popupScale);popupScale=next;clampPanel();}
 void reload(){if(runner.pending){reloadRequested=true;runner.pause("Paused · finishing before settings update");}else edit(()->replace(AutoTapStore.load(service)));}
 void showMarkers(){if(closed||runner.playing||runner.pending||!markerVisible)return;for(int i=0;i<plan.points.size();i++){final int index=i;AutoTapPlan.Point p=plan.points.get(i);TextView marker=Ui.label(service,""+(i+1),18,Ui.BG);marker.setGravity(Gravity.CENTER);marker.setTypeface(Ui.display(service));marker.setBackground(Ui.shape(service,Ui.GREEN,Ui.CREAM,28));marker.setContentDescription("Target "+(i+1)+". Drag to position; tap to edit.");marker.setFocusable(true);int size=Ui.dp(service,48);WindowManager.LayoutParams lp=params(size,size);lp.x=x(p)-size/2;lp.y=y(p)-size/2;marker.setOnClickListener(v->edit(()->AutoTapUi.point(service,plan,index,this::replace)));marker.setOnTouchListener(new View.OnTouchListener(){float sx,sy,px,py;boolean moved;public boolean onTouch(View v,MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){sx=e.getRawX();sy=e.getRawY();px=p.x*width;py=p.y*height;moved=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.abs(dx)+Math.abs(dy)>Ui.dp(service,4))moved=true;if(moved){p.x=Math.max(0,Math.min(1,(px+dx)/width));p.y=Math.max(0,Math.min(1,(py+dy)/height));lp.x=x(p)-size/2;lp.y=y(p)-size/2;wm.updateViewLayout(marker,lp);}return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){if(moved){AutoTapStore.save(service,plan);}else if(e.getActionMasked()==MotionEvent.ACTION_UP)v.performClick();return true;}return true;}});wm.addView(marker,lp);markers.add(marker);}}
